const result = [];
for (const [index, item] of $input.all().entries()) {
  const event = item.json;
  if (event.field !== 'messages' || event.metadata?.phone_number_id !== '1526007707255136') continue;
  for (const m of event.messages ?? []) {
    if (m.from !== 'DEMO_REMITENTE_META' || m.type !== 'text' || !m.id?.trim() || !m.text?.body?.trim()) continue;
    result.push({json:{message_id:m.id, from:m.from, phone_number_id:event.metadata.phone_number_id, text:m.text.body}, pairedItem:{item:index}});
  }
}
return result;

const output = [];
for (const [index, item] of $input.all().entries()) {
  const event = item.json;
  const phoneId = event.metadata?.phone_number_id;
  if (event.field !== 'messages' || phoneId !== '1526007707255136') continue;
  for (const update of event.statuses ?? []) {
    if (update.recipient_id !== 'DEMO_REMITENTE_META' && update.recipient_id !== 'DEMO_DESTINATARIO_META') continue;
    output.push({
      json: { message_id: update.id, phone_number_id: phoneId, status: update.status },
      pairedItem: { item: index }
    });
  }
}
return output;

// Habilitar después de aprobar y preparar los registros demo.
const habilitada = false;
return habilitada ? $input.all() : [];

const r=$json.body?.[0];
if ($json.body?.length !== 1 || r.conversation_id !== "DEMO_CONVERSACION_UUID" || !r.message_id || !Number.isSafeInteger(r.history_position) || typeof r.created !== 'boolean') throw new Error('Ingreso inesperado');
return {json:{...r,mensaje:$('Procesar cada mensaje').item.json.text}};

const actual=$('Mensaje registrado').itemMatching(0).json;
const rows = $input.all().flatMap(p => {
  if (!Array.isArray(p.json.body)) throw new Error('Página de historial inválida.');
  return p.json.body;
});
let anterior = 0;
const ids = new Set();
const historial = rows.map(r => {
  if (!Number.isSafeInteger(r.history_position) || r.history_position <= anterior || r.history_position >= actual.history_position ||
      !r.message_id || r.message_id === actual.message_id || ids.has(r.message_id) || !['bot','customer'].includes(r.sender_kind))
    throw new Error('Página fuera de orden, autor inválido o mensaje repetido.');
  anterior = r.history_position; ids.add(r.message_id);
  return (r.sender_kind === 'customer' ? 'Cliente: ' : 'Bot: ') + r.body;
});

return [{json:{mensaje:actual.mensaje,historial:historial.join('\n')},pairedItem:{item:0}}];

